class Doc(BaseDocTemplate):
 def __init__(self,filename,label,**kw):self.label=label;super().__init__(filename,**kw);self.addPageTemplates(PageTemplate(id='main',frames=Frame(self.leftMargin,self.bottomMargin,self.width,self.height,id='f'),onPage=self.art))
 def art(self,c,doc):c.saveState();c.setFillColor(base.BG);c.rect(0,0,A4[0],A4[1],fill=1,stroke=0);c.setStrokeColor(base.BORDER);c.line(20*mm,15*mm,A4[0]-20*mm,15*mm);c.setFillColor(base.MUTED);c.setFont('Helvetica',8);c.drawString(20*mm,9*mm,f'DevVault  |  {self.label}');c.drawRightString(A4[0]-20*mm,9*mm,str(doc.page));c.restoreState()
 def afterFlowable(self,f):
  if isinstance(f,Paragraph) and f.style.name in ('Chapter','H2'):
   level=0 if f.style.name=='Chapter' else 1;text=f.getPlainText();key=f'h{level}-{self.seq.nextf("h")}';self.canv.bookmarkPage(key);self.canv.addOutlineEntry(text,key,level=level,closed=False);self.notify('TOCEntry',(level,text,self.page,key))

def make_pdf(path,title,subtitle,chapters,sample=False):
 s=base.styles();story=[Spacer(1,27*mm),Paragraph(title.upper(),s['title']),Paragraph(subtitle,s['sub']),Spacer(1,10*mm),Table([[('PUBLIC SAMPLE' if sample else 'PROFESSIONAL GUIDE')],['DevVault Digital Product Series'],[f'{len(chapters)} practical chapters'],['Edition 1.0  |  October 2026']],colWidths=[160*mm],style=TableStyle([('BACKGROUND',(0,0),(-1,0),base.VIOLET),('BACKGROUND',(0,1),(-1,-1),base.PLUM),('TEXTCOLOR',(0,0),(-1,-1),base.IVORY),('BOX',(0,0),(-1,-1),1,base.BORDER),('LEFTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8)])),Spacer(1,8*mm),Paragraph('Educational and implementation guidance only. Verify external services, versions, policies, and security requirements for your environment. No outcome, security, or compliance guarantee is made.',s['small']),PageBreak()]
 chosen=chapters[:3] if sample else chapters
 if sample:story += [Paragraph('Inside this limited sample',s['chapter']),Paragraph('This preview includes introductory material and selected examples. Complete templates, source archives, operational guidance, and the remaining chapters are paid deliverables.',s['body']),PageBreak()]
 else:story += [Paragraph('Contents',s['chapter'])];toc=TableOfContents();toc.levelStyles=[s['toc0'],s['toc1']];story += [toc,PageBreak()]
 for i,name in enumerate(chosen,1):
  explain=f'{name} is treated as an explicit engineering boundary rather than a slogan. Start from users, data, trust, failure impact, operating constraints, and verifiable acceptance evidence. The recommended workflow separates assumptions from observed behavior, records ownership, and preserves a safe rollback or rejection path.'
  guidance=f'Define the intended outcome and exclusions; identify inputs, outputs, owners, and trust boundaries; validate normal and negative behavior; record evidence without secrets; document failure handling and rollback'
  mistakes='Copying configuration without understanding it; accepting client claims as authority; omitting negative tests; recording credentials in examples; claiming production readiness without operational evidence'
  exercise=f'Apply {name.lower()} to the included example project or worksheet. Expected outcome: a documented decision, reproducible validation, named owner, unresolved risks, and next review date.'
  code=f'REVIEW: {name}\nstatus: draft\nowner: named-role\nevidence: test-or-document-reference\ndecision: accept / revise / reject'
  story += base.chapter((name,explain,guidance,mistakes,exercise,['REQUIRE','DESIGN','VALIDATE','REVIEW','OPERATE'],code),i,s)
 if not sample:story += [Paragraph('Final delivery checklist',s['chapter']),Paragraph('Confirm the documented versions, install from the lockfile, validate configuration without exposing values, run type checks, lint, tests, and the production build, review authorization and data boundaries, and retain rollback instructions. A successful build is evidence of compatibility—not proof of production readiness.',s['body'])]
 Doc(str(path),title,pagesize=A4,leftMargin=20*mm,rightMargin=20*mm,topMargin=20*mm,bottomMargin=22*mm,title=title,author='DevVault').multiBuild(story)

def ai_template(title,purpose):
 return f'''# {title}\n\n## Purpose\n{purpose}\n\n## Instructions\nComplete this with the workflow owner and an independent reviewer. Use only approved, minimized context. Never paste credentials, private customer data, access tokens, or confidential source material into an unapproved model.\n\n## Decision record\n| Field | Value |\n|---|---|\n| Use case / workflow | |\n| Owner | |\n| Reviewer | |\n| Prompt or workflow version | |\n| Approved data classes | Public / Internal / Other approved class |\n| Prohibited data | Credentials, tokens, unapproved personal or confidential data |\n| Review date / next review | |\n| Status | Draft / Pilot / Approved with controls / Rejected |\n\n## Workflow\n1. Define a measurable task and what the model must not decide.\n2. Provide authoritative, minimal context and label untrusted content as data.\n3. Require a structured response, uncertainty, and source references where applicable.\n4. Validate syntax or schema mechanically, then verify material claims independently.\n5. Require a named human to accept, revise, or reject the output.\n6. Record failure cases and add them to a versioned regression set.\n\n## Acceptance criteria\n- [ ] Output follows the requested contract and contains no prohibited data.\n- [ ] Material factual claims are supported or explicitly marked uncertain.\n- [ ] Code, SQL, or configuration is tested in an appropriate isolated development environment.\n- [ ] Security and authorization decisions remain under trusted server or human control.\n- [ ] A reviewer records evidence, decision, rationale, and date.\n\n## Safe example\nTask: draft test ideas for an ownership-protected download endpoint. Expected review: anonymous and cross-user denial, paid-owner access, inactive-asset denial, traversal resistance, safe headers, and no token logging. The model proposes candidates; the team implements and verifies them.\n\n## Findings and escalation\n| ID | Observation | Impact | Required action | Owner | Due date | Evidence | Status |\n|---|---|---|---|---|---|---|---|\n| EX-001 | Replace this example with a real evaluated result | Medium | Add to regression set and retest | Workflow owner | YYYY-MM-DD | Safe test reference | Open |\n'''

