def safe_zip(source,target,arcroot):
 with zipfile.ZipFile(target,'w',zipfile.ZIP_DEFLATED) as z:
  for p in sorted(source.rglob('*')):
   if p.is_file() and 'node_modules' not in p.parts and '.next' not in p.parts:z.write(p,f'{arcroot}/{p.relative_to(source)}')

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--output-dir',type=Path,required=True);ap.add_argument('--zip-only',action='store_true');a=ap.parse_args();a.output_dir.mkdir(parents=True,exist_ok=True)
 if not a.zip_only:
  ai=a.output_dir/'ai-copilot-workflow-pack';ed=ai/'editable-workflows';ed.mkdir(parents=True,exist_ok=True)
  for fn,title,purpose in AI_TEMPLATES:
   if fn.endswith('.csv'):
    with (ed/fn).open('w',newline='',encoding='utf-8') as h:csv.writer(h).writerows([['criterion','weight','score_1_guidance','score_3_guidance','score_5_guidance','evidence','reviewer','review_date'],[title,'20','Unsupported or unsafe','Partially supported; revision needed','Supported, validated, and accepted','Safe reference','','YYYY-MM-DD']])
   elif fn.endswith('.json'):(ed/fn).write_text(json.dumps({'purpose':purpose,'cases':[{'id':'REG-001','input':'Safe synthetic request','expectedProperties':['structured output','uncertainty disclosed','no sensitive data'],'forbidden':['invented evidence','credentials'],'reviewer':'','status':'draft'}]},indent=2)+'\n')
   else:(ed/fn).write_text(ai_template(title,purpose))
  (ed/'README.md').write_text('# AI Copilot Workflow Pack\n\nTwenty editable resources for evaluated, human-reviewed AI-assisted work. Start with use-case selection, apply data protection and injection controls, version prompts, evaluate outputs, and retain accountable human acceptance. These templates do not make model output trustworthy by themselves.\n')
  make_pdf(ai/'ai-copilot-workflow-pack-companion-guide-v1.pdf','AI Copilot Workflow Pack','Grounded prompts, evaluation, safety, and human-governed workflows',AI_CHAPTERS);make_pdf(ai/'ai-copilot-workflow-pack-public-sample-v1.pdf','AI Copilot Workflow Pack','A limited introduction to evaluated AI-assisted workflows',AI_CHAPTERS,True)
  fs=a.output_dir/'full-stack-starter-kit';ns=a.output_dir/'nextjs-launch-kit';write_project(fs/'source','full-stack-starter');write_project(ns/'source','nextjs-launch-kit')
  make_pdf(fs/'full-stack-starter-kit-setup-guide-v1.pdf','Full-Stack Starter Kit','Architecture, setup, security boundaries, testing, and deployment guidance',FULL_CHAPTERS);make_pdf(fs/'full-stack-starter-kit-public-sample-v1.pdf','Full-Stack Starter Kit','Feature, architecture, and setup preview',FULL_CHAPTERS,True)
  make_pdf(ns/'nextjs-launch-kit-guide-v1.pdf','Next.js Launch Kit','Reusable layouts, accessibility, responsive design, SEO, and launch workflow',LAUNCH_CHAPTERS);make_pdf(ns/'nextjs-launch-kit-public-sample-v1.pdf','Next.js Launch Kit','Selected website architecture and setup material',LAUNCH_CHAPTERS,True)
 safe_zip(a.output_dir/'ai-copilot-workflow-pack'/'editable-workflows',a.output_dir/'ai-copilot-workflow-pack'/'ai-copilot-workflow-pack-editable-v1.zip','ai-copilot-workflows')
 safe_zip(a.output_dir/'full-stack-starter-kit'/'source',a.output_dir/'full-stack-starter-kit'/'full-stack-starter-kit-source-v1.zip','full-stack-starter-kit')
 safe_zip(a.output_dir/'nextjs-launch-kit'/'source',a.output_dir/'nextjs-launch-kit'/'nextjs-launch-kit-source-v1.zip','nextjs-launch-kit')
 print('generated remaining marketplace deliverables')
if __name__=='__main__':main()
